using System.IO.Compression;
using System.Text.Json;
using VisionCore;
using VisionPlugins.DistortionCalibration;
using var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/distortion-calibration-pixel-evidence.json"));var reports=new List<object>();byte[] Inflate(string encoded){using var input=new MemoryStream(Convert.FromBase64String(encoded));using var zlib=new ZLibStream(input,CompressionMode.Decompress);using var output=new MemoryStream();zlib.CopyTo(output);return output.ToArray();}
foreach(var row in evidence.RootElement.GetProperty("cases").EnumerateArray()){var native=row.GetProperty("native");var file=new DistortionCalibrationFile(native.GetProperty("matrix").EnumerateArray().Select(e=>(float)e.GetDouble()));var input=Inflate(row.GetProperty("inputZlibBase64").GetString()!);var expected=Inflate(row.GetProperty("correctedZlibBase64").GetString()!);var actual=new DistortionCalibrationWarp(file).Correct(new GrayImage(file.Width,file.Height,input)).Pixels.ToArray();var delta=expected.Zip(actual).Select(p=>Math.Abs(p.First-p.Second)).ToArray();if(delta.Any(v=>v!=0))throw new Exception($"Native remap pixel mismatch: model {file.Model}");reports.Add(new{board=native.GetProperty("board").GetInt32(),model=file.Model,warp=native.GetProperty("warp").GetInt32(),pixels=delta.Length,exact=delta.Count(v=>v==0),maximum=delta.Max(),average=delta.Average()});}
Directory.CreateDirectory("analysis/distortion-calibration/pixel-verification");string json=JsonSerializer.Serialize(new{scope="Source-backed remap acceptance for twelve original Mono8 fixtures; calibration fit/RGB/native UI not covered",reports},new JsonSerializerOptions{WriteIndented=true});File.WriteAllText("analysis/distortion-calibration/pixel-verification/report.json",json);Console.WriteLine(json);

using var inverseEvidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/distortion-calibration-inverse-radial-evidence.json"));int inverseCount=0,inverseBits=0;double inverseMaximum=0;
foreach(var row in inverseEvidence.RootElement.GetProperty("cases").EnumerateArray()){double[] Pair(string name)=>row.GetProperty(name).EnumerateArray().Select(x=>x.GetDouble()).ToArray();var p=Pair("input");var c=Pair("center");var r=Pair("radial");var expected=Pair("ideal");var actual=DistortionCalibrationInverseRadial.Solve(new(p[0],p[1]),new(c[0],c[1]),r.Select(x=>(float)x).ToArray());double error=Math.Max(Math.Abs(actual.X-(float)expected[0]),Math.Abs(actual.Y-(float)expected[1]));inverseMaximum=Math.Max(inverseMaximum,error);inverseBits+=(float)actual.X==(float)expected[0]?1:0;inverseBits+=(float)actual.Y==(float)expected[1]?1:0;if(error>0.0001)throw new Exception($"Original inverse radial differs by {error:R}");inverseCount++;}
var controlledObserved=new Point2(12,34);var controlledFailure=DistortionCalibrationInverseRadial.Solve(controlledObserved,new Point2(0,0),new[]{float.PositiveInfinity,0f,1f,0f});
if(controlledFailure!=controlledObserved)throw new Exception("Failed two-variable LM must return its initial observed point");
Console.WriteLine("Controlled inverse failure uses initial observed fallback; not a native nonfinite-input parity claim.");
Console.WriteLine($"Inverse radial: {inverseCount} native points, {inverseBits}/{inverseCount*2} float fields exact; maximum {inverseMaximum:R}");

